View.TextArea:
'.actionBtn': {
  apply: 'mb-2 mr-2 h-8 w-20 rounded-lg
    text-xs font-semibold text-white'
}

// Every Label gets these styles
Label: {
  apply: 'text-base font-bold text-gray-700'
}

// Windows on iOS get large title setup
Window: {
  ios: {
    apply: 'auto-adjust-scroll-view-insets
      extend-edges-all large-title-enabled
      status-bar-style-light-content'
  }
}

'#carrousel': {
  apply: 'w-screen h-auto bg-teal-200
    mx-2 my-4 horizontal'
}

extend: {
  colors: {
    corporate: {
      100: '#dddfe1', 200: '#babfc4',
      500: '#53606b'
    }
  }
},
'.btn-corporate': {
  apply: 'bg-corporate-500
    text-corporate-100
    border-corporate-200'
}
// → bg, text, and border all use
//   the newly created colors

'.btn': {
  apply: 'font-bold border-2 rounded
    wh-auto my-0.5',

  ios: { apply: 'w-screen mx-4' },
  handheld: { apply: 'h-20' },

  '[if=Alloy.Globals.iPhoneX]': {
    apply: 'mb-12'
  }
}

'.my-view': {
  apply: 'wh-32 bg-green-500',
  ios: { apply: 'clip-enabled' }
}
// → '.my-view[platform=ios]': {
//     clipMode: Ti.UI.iOS.CLIP_MODE_ENABLED,
//     ... }

'.progress': {
  apply: 'h-(1rem) horizontal
    bg-(#e9ecef) text-(.75rem)
    rounded-(.25rem)'
}
// → height: 16, layout: 'horizontal',
//   fontSize: 12, borderRadius: 4
